"use client";

import { ArrowLeft, ArrowRight, Check, Copy, RotateClockwise as RotateCw } from "@nebutra/icons";
import type { CSSProperties, HTMLAttributes, ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "../utils/cn";
import { MiddleTruncate } from "./middle-truncate";

const COPIED_FEEDBACK_MS = 1500;

/* -------------------------------------------------------------------------- *\
 *  Browser — Geist-style browser chrome around a screenshot, demo, or video.
 *
 *  Use cases (per Geist guidance):
 *    - Marketing chrome on landing pages, docs, changelog posts.
 *    - Do NOT render real product UI here — the chrome implies a screenshot,
 *      not a live surface.
 *
 *  Behavior rules:
 *    - Chrome (dots + nav arrows) is decorative. Wrapped in `aria-hidden="true"`.
 *    - Address bar uses middle truncation so the host and path tail both
 *      remain visible on long URLs. The copy button is the one real,
 *      reachable interaction.
 *    - Image-mode viewport locks an aspect ratio (default 16:9) so the chrome
 *      doesn't reflow when the image is missing or slow to load. Children mode
 *      defers sizing to the consumer's own JSX.
 *
 *  Content slots — discriminated:
 *    Pass exactly one of:
 *      - `children`         → arbitrary JSX (consumer owns aspect lock)
 *      - `imageSrc + imageAlt` → framework-neutral <img> tag, alt required
 *    Both unrepresentable: the TS union forbids it. Use the children form
 *    when you need next/image or a video.
\* -------------------------------------------------------------------------- */

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

type BaseProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  /** URL displayed in the address bar (host + path). */
  address?: string;
  /**
   * Inner viewport aspect ratio. Number is width/height (e.g. `16/9 = 1.777`).
   * String passes directly to CSS `aspect-ratio` (e.g. `"16 / 9"`, `"4 / 3"`).
   *
   * Defaults: `"16 / 9"` in image mode (prevents layout shift on slow load),
   * undefined in children mode (consumer JSX owns sizing).
   */
  aspectRatio?: number | string;
};

type ChildrenProps = BaseProps & {
  children: ReactNode;
  imageSrc?: never;
  imageAlt?: never;
};

type ImageProps = BaseProps & {
  children?: never;
  imageSrc: string;
  imageAlt: string;
};

export type BrowserProps = ChildrenProps | ImageProps;

/** @deprecated Use `BrowserProps` instead. */
export type BrowserMockupProps = BrowserProps;

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * @example Children mode
 * ```tsx
 * <Browser address="vercel.com"><MyDemo /></Browser>
 * ```
 *
 * @example Image mode (alt required)
 * ```tsx
 * <Browser
 *   address="vercel.com/dashboard"
 *   imageSrc="/dashboard.png"
 *   imageAlt="Dashboard showing the current month's deployments and bandwidth usage"
 * />
 * ```
 */
export function Browser(props: BrowserProps) {
  const {
    address,
    aspectRatio,
    className,
    // children path
    children,
    // image path
    imageSrc,
    imageAlt,
    ...rest
  } = props as BaseProps & {
    children?: ReactNode;
    imageSrc?: string;
    imageAlt?: string;
  };

  // Children mode → defer aspect to the consumer (their JSX may already be
  // height-constrained). Image mode → default to 16:9 so the chrome doesn't
  // reflow when the image is missing or slow to load.
  const resolvedRatio = aspectRatio ?? (imageSrc ? "16 / 9" : undefined);

  const [copied, setCopied] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const handleCopy = useCallback(async () => {
    if (!address) return;
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
    } catch {
      // Clipboard API may be blocked (insecure context, iframe sandbox).
    }
  }, [address]);

  const viewportStyle: CSSProperties =
    resolvedRatio !== undefined
      ? {
          aspectRatio: typeof resolvedRatio === "number" ? `${resolvedRatio} / 1` : resolvedRatio,
        }
      : {};

  return (
    <div
      className={cn(
        "overflow-hidden rounded-[var(--radius-xl)] border border-border bg-card shadow-sm",
        className,
      )}
      {...rest}
    >
      {/* ── Chrome toolbar — decorative ──────────────────────────────── */}
      <div className="flex items-center gap-3 border-border border-b bg-muted px-4 py-2.5">
        <div className="flex items-center gap-1.5" aria-hidden="true">
          <span className="size-3 rounded-full bg-destructive" />
          <span className="size-3 rounded-full bg-warning" />
          <span className="size-3 rounded-full bg-success" />
        </div>

        <div className="flex items-center gap-1" aria-hidden="true">
          <span className="flex size-6 items-center justify-center rounded text-muted-foreground">
            <ArrowLeft className="size-3.5" />
          </span>
          <span className="flex size-6 items-center justify-center rounded text-muted-foreground">
            <ArrowRight className="size-3.5" />
          </span>
          <span className="flex size-6 items-center justify-center rounded text-muted-foreground">
            <RotateCw className="size-3.5" />
          </span>
        </div>

        {/* Address bar — middle-truncate keeps host visible AND path tail */}
        <div className="flex flex-1 items-center justify-center gap-2 rounded-[var(--radius-md)] bg-background/80 px-3 py-1">
          {address ? (
            <>
              <MiddleTruncate
                value={address}
                className="min-w-0 flex-1 text-center text-muted-foreground text-xs"
              />
              <button
                type="button"
                onClick={handleCopy}
                aria-label={copied ? "Address copied" : "Copy address"}
                className="flex-shrink-0 rounded p-0.5 text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none"
              >
                {copied ? <Check className="size-3" /> : <Copy className="size-3" />}
              </button>
            </>
          ) : (
            <span className="h-3" />
          )}
        </div>
      </div>

      {/* ── Inner viewport — aspect-locked ──────────────────────────── */}
      <div className="relative bg-background" style={viewportStyle}>
        {children ??
          (imageSrc ? (
            // biome-ignore lint/performance/noImgElement: framework-neutral primitive — consumers may not be on Next.js
            <img
              src={imageSrc}
              alt={imageAlt ?? ""}
              decoding="async"
              loading="lazy"
              className="absolute inset-0 block h-full w-full object-cover"
            />
          ) : (
            <div className="absolute inset-0 flex items-center justify-center bg-muted text-muted-foreground text-sm">
              No content
            </div>
          ))}
      </div>
    </div>
  );
}

Browser.displayName = "Browser";

/** @deprecated Use `Browser` instead. */
export const BrowserMockup = Browser;

"use client";

import * as React from "react";
import { cn } from "../utils/cn";

const DEFAULT_MIN_START_CHARS = 6;
const DEFAULT_MIN_END_CHARS = 8;
const DEFAULT_ELLIPSIS = "…";

type TruncationParts = {
  head: string;
  tail: string;
  truncated: boolean;
};

export interface MiddleTruncateProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children"> {
  /**
   * Full text value. The visible text may be shortened, but copy and
   * assistive technology keep this original string.
   */
  value: string;
  /** Minimum characters to preserve at the start when space allows. */
  minStartChars?: number;
  /** Minimum characters to preserve at the end when space allows. */
  minEndChars?: number;
  /** Separator rendered between the preserved head and tail. */
  ellipsis?: string;
}

function getCanvasContext(): CanvasRenderingContext2D | null {
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  return canvas.getContext("2d");
}

function getCanvasFont(style: CSSStyleDeclaration): string {
  if (style.font) return style.font;
  const fontStyle = style.fontStyle || "normal";
  const fontVariant = style.fontVariant || "normal";
  const fontWeight = style.fontWeight || "400";
  const fontSize = style.fontSize || "14px";
  const lineHeight = style.lineHeight || "normal";
  const fontFamily = style.fontFamily || "sans-serif";
  return `${fontStyle} ${fontVariant} ${fontWeight} ${fontSize}/${lineHeight} ${fontFamily}`;
}

function splitForBudget(
  glyphs: string[],
  visibleGlyphCount: number,
  minStartChars: number,
  minEndChars: number,
): { head: string; tail: string } {
  if (visibleGlyphCount <= 0) return { head: "", tail: "" };

  const length = glyphs.length;
  const normalizedMinStart = Math.max(1, Math.min(minStartChars, length));
  const normalizedMinEnd = Math.max(1, Math.min(minEndChars, length));

  let headCount: number;
  let tailCount: number;

  if (visibleGlyphCount <= normalizedMinStart + normalizedMinEnd) {
    headCount = Math.ceil(visibleGlyphCount / 2);
    tailCount = visibleGlyphCount - headCount;
  } else {
    const extra = visibleGlyphCount - normalizedMinStart - normalizedMinEnd;
    headCount = normalizedMinStart + Math.ceil(extra / 2);
    tailCount = normalizedMinEnd + Math.floor(extra / 2);
  }

  if (headCount + tailCount >= length) {
    tailCount = Math.max(1, length - headCount - 1);
  }

  return {
    head: glyphs.slice(0, headCount).join(""),
    tail: tailCount > 0 ? glyphs.slice(length - tailCount).join("") : "",
  };
}

function computeMiddleTruncation(
  value: string,
  width: number,
  font: string,
  ellipsis: string,
  minStartChars: number,
  minEndChars: number,
): TruncationParts {
  const glyphs = Array.from(value);
  if (glyphs.length === 0) return { head: "", tail: "", truncated: false };
  if (font.length === 0) return { head: value, tail: "", truncated: false };
  if (width <= 0) return { head: "", tail: "", truncated: true };

  const context = getCanvasContext();
  if (!context) return { head: value, tail: "", truncated: false };
  context.font = font;

  const measure = (text: string) => context.measureText(text).width;
  if (measure(value) <= width) return { head: value, tail: "", truncated: false };

  const ellipsisWidth = measure(ellipsis);
  if (ellipsisWidth >= width) return { head: "", tail: "", truncated: true };

  let low = 0;
  let high = glyphs.length - 1;
  let best: TruncationParts = { head: "", tail: "", truncated: true };

  while (low <= high) {
    const visibleGlyphCount = Math.floor((low + high) / 2);
    const candidate = splitForBudget(glyphs, visibleGlyphCount, minStartChars, minEndChars);
    const candidateWidth = measure(`${candidate.head}${ellipsis}${candidate.tail}`);

    if (candidateWidth <= width) {
      best = { ...candidate, truncated: true };
      low = visibleGlyphCount + 1;
    } else {
      high = visibleGlyphCount - 1;
    }
  }

  return best;
}

function assignRef<T>(ref: React.Ref<T> | undefined, value: T | null): void {
  if (typeof ref === "function") {
    ref(value);
    return;
  }

  if (ref) {
    ref.current = value;
  }
}

const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

export const MiddleTruncate = ({
  value,
  minStartChars = DEFAULT_MIN_START_CHARS,
  minEndChars = DEFAULT_MIN_END_CHARS,
  ellipsis = DEFAULT_ELLIPSIS,
  className,
  onCopy,
  "aria-label": ariaLabel,
  ref: forwardedRef,
  ...props
}: MiddleTruncateProps & { ref?: React.Ref<HTMLSpanElement> | undefined }) => {
  const localRef = React.useRef<HTMLSpanElement | null>(null);
  const [measurements, setMeasurements] = React.useState({ width: 0, font: "" });

  const setRef = React.useCallback(
    (node: HTMLSpanElement | null) => {
      localRef.current = node;
      assignRef(forwardedRef, node);
    },
    [forwardedRef],
  );

  useIsomorphicLayoutEffect(() => {
    const node = localRef.current;
    if (!node) return undefined;

    let frame = 0;
    const updateMeasurements = () => {
      frame = 0;
      const style = window.getComputedStyle(node);
      const container = node.parentElement ?? node;
      setMeasurements({
        width: container.getBoundingClientRect().width,
        font: getCanvasFont(style),
      });
    };

    const scheduleUpdate = () => {
      if (frame) return;
      frame = window.requestAnimationFrame(updateMeasurements);
    };

    updateMeasurements();

    if (document.fonts) {
      void document.fonts.ready.then(scheduleUpdate);
    }

    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", scheduleUpdate);
      return () => {
        if (frame) window.cancelAnimationFrame(frame);
        window.removeEventListener("resize", scheduleUpdate);
      };
    }

    const observer = new ResizeObserver(scheduleUpdate);
    observer.observe(node.parentElement ?? node);

    return () => {
      if (frame) window.cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, []);

  const parts = React.useMemo(
    () =>
      computeMiddleTruncation(
        value,
        measurements.width,
        measurements.font,
        ellipsis,
        minStartChars,
        minEndChars,
      ),
    [ellipsis, measurements.font, measurements.width, minEndChars, minStartChars, value],
  );

  const handleCopy = React.useCallback(
    (event: React.ClipboardEvent<HTMLSpanElement>) => {
      onCopy?.(event);
      if (event.defaultPrevented) return;
      event.clipboardData.setData("text/plain", value);
      event.preventDefault();
    },
    [onCopy, value],
  );

  const visibleText = parts.truncated ? `${parts.head}${ellipsis}${parts.tail}` : value;
  const hasAccessibleOverride = ariaLabel !== undefined;
  const hideVisibleTextFromAssistiveTech = parts.truncated || hasAccessibleOverride;

  return (
    <span
      ref={setRef}
      className={cn("inline-block min-w-0 max-w-full whitespace-nowrap", className)}
      data-truncated={parts.truncated ? "" : undefined}
      onCopy={handleCopy}
      {...props}
    >
      <span aria-hidden={hideVisibleTextFromAssistiveTech ? "true" : undefined}>{visibleText}</span>
      {hideVisibleTextFromAssistiveTech && <span className="sr-only">{ariaLabel ?? value}</span>}
    </span>
  );
};

MiddleTruncate.displayName = "MiddleTruncate";
